import networkx as nx
from itertools import product

def roman_dom(G):
    # compute roman domination number
    nodes = list(G.nodes())
    n = len(nodes)
    best = 2 * n
    for f in product([0, 1, 2], repeat=n):
        # check if roman dominating
        valid = True
        for i, u in enumerate(nodes):
            if f[i] == 0:
                # must have neighbor with 2
                has_two = any(f[nodes.index(v)] == 2 for v in G.neighbors(u))
                if not has_two:
                    valid = False
                    break
        if valid:
            cost = sum(f)
            if cost < best:
                best = cost
    return best

